import{_ as i,o as a,c as n,a2 as t}from"./chunks/framework.BjkiRu3Q.js";const c=JSON.parse('{"title":"GitHub Actions 当定时任务用","description":"","frontmatter":{"title":"GitHub Actions 当定时任务用"},"headers":[],"relativePath":"md/devops/actions-cron.md","filePath":"md/devops/actions-cron.md","lastUpdated":1795424423000}'),l={name:"md/devops/actions-cron.md"};function e(h,s,p,o,k,r){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="github-actions-当定时任务用" tabindex="-1">GitHub Actions 当定时任务用 <a class="header-anchor" href="#github-actions-当定时任务用" aria-label="Permalink to &quot;GitHub Actions 当定时任务用&quot;">​</a></h1><p>用 Actions 的 <code>schedule</code> 触发跑定期任务（抓数据、生成报表、检查站点），是个门槛极低的方案。但把它当 cron 用之前，得先知道它和真 cron 的差别。</p><h2 id="五个必须知道的边界" tabindex="-1">五个必须知道的边界 <a class="header-anchor" href="#五个必须知道的边界" aria-label="Permalink to &quot;五个必须知道的边界&quot;">​</a></h2><h3 id="_1-cron-是-尽力而为-不保证准时" tabindex="-1">1. cron 是&quot;尽力而为&quot;，不保证准时 <a class="header-anchor" href="#_1-cron-是-尽力而为-不保证准时" aria-label="Permalink to &quot;1. cron 是&quot;尽力而为&quot;，不保证准时&quot;">​</a></h3><p>官方明确说过定时触发可能延迟，负载高峰时延迟十几分钟很常见，个别情况更久。所以：</p><ul><li><strong>不要依赖精确时刻</strong>。任务里如果要&quot;取当天零点数据&quot;，自己算，不要假设触发时就是零点。</li><li><strong>重要任务加一个兜底触发</strong>，比如另一个时间点跑一次，用幂等逻辑去重。</li></ul><h3 id="_2-仓库-60-天无活动-定时任务会被停用" tabindex="-1">2. 仓库 60 天无活动，定时任务会被停用 <a class="header-anchor" href="#_2-仓库-60-天无活动-定时任务会被停用" aria-label="Permalink to &quot;2. 仓库 60 天无活动，定时任务会被停用&quot;">​</a></h3><p>公开仓库的 <code>schedule</code> 在 60 天没有任何 commit 活动后会被自动禁用。如果任务是&quot;有变化才提交&quot;，很可能几十天不提交，然后任务静默停掉。</p><p>规避方式：定期做一次空提交、或者任务里更新一个心跳文件。</p><h3 id="_3-免费额度和私有仓库不一样" tabindex="-1">3. 免费额度和私有仓库不一样 <a class="header-anchor" href="#_3-免费额度和私有仓库不一样" aria-label="Permalink to &quot;3. 免费额度和私有仓库不一样&quot;">​</a></h3><p>公开仓库的标准 runner 免费不限量；私有仓库按账户额度计费。长期跑高频任务（比如每 15 分钟一次）会吃掉大量额度。做数据采集这类任务，公开仓库更划算，但要注意别把敏感配置放进去。</p><h3 id="_4-无状态-每次都是干净环境" tabindex="-1">4. 无状态，每次都是干净环境 <a class="header-anchor" href="#_4-无状态-每次都是干净环境" aria-label="Permalink to &quot;4. 无状态，每次都是干净环境&quot;">​</a></h3><p>每次运行都是全新容器：上次写的文件、装的包、缓存的登录态全没有。</p><p>能用的持久化只有三种：</p><ul><li>提交回仓库（简单，但会污染历史）</li><li>Actions Cache（有大小和淘汰策略，不能当数据库）</li><li>外部存储（对象存储、数据库、Gist）</li></ul><h3 id="_5-默认-token-权限很有限" tabindex="-1">5. 默认 token 权限很有限 <a class="header-anchor" href="#_5-默认-token-权限很有限" aria-label="Permalink to &quot;5. 默认 token 权限很有限&quot;">​</a></h3><p><code>GITHUB_TOKEN</code> 只对当前仓库有权限，且默认只读。要 push 回去得显式声明：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">permissions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  contents</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">write</span></span></code></pre></div><p>要访问其他仓库或者调 API，才需要 Personal Access Token。这类 token 放 Secrets，不要写在 workflow 文件里。</p><h2 id="一个能长期跑的最小结构" tabindex="-1">一个能长期跑的最小结构 <a class="header-anchor" href="#一个能长期跑的最小结构" aria-label="Permalink to &quot;一个能长期跑的最小结构&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">collect</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  schedule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cron</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0 */6 * * *&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 注意是 UTC</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  workflow_dispatch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 留个人工触发入口，调试必需</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">jobs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    runs-on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ubuntu-latest</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    permissions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      contents</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">write</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    steps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">actions/checkout@v4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./scripts/collect.sh</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./scripts/commit-if-changed.sh</span></span></code></pre></div><p><code>workflow_dispatch</code> 那一行很重要。调试的时候你不可能等到下一个定时点，有手动触发入口，一次排查能从半小时降到两分钟。</p><h2 id="cron-表达式有个坑" tabindex="-1">cron 表达式有个坑 <a class="header-anchor" href="#cron-表达式有个坑" aria-label="Permalink to &quot;cron 表达式有个坑&quot;">​</a></h2><p>Actions 的 cron 用 <strong>UTC</strong>，不是本地时间。国内要跑&quot;每天早上 8 点&quot;，得写 <code>0 0 * * *</code>（UTC 0 点 = 北京 8 点）。</p><p>夏令时地区更麻烦，一年要改两次。用 UTC 固定时间、或者干脆按&quot;每 N 小时&quot;跑，比绑死本地时刻稳。</p><h2 id="什么时候该换方案" tabindex="-1">什么时候该换方案 <a class="header-anchor" href="#什么时候该换方案" aria-label="Permalink to &quot;什么时候该换方案&quot;">​</a></h2><p>出现这些信号时，说明该上真服务器了：</p><ul><li>需要任务间隔小于 5 分钟</li><li>需要单次运行超过 6 小时</li><li>需要常驻进程（WebSocket 监听、长轮询）</li><li>需要本地磁盘长期保存中间文件</li><li>任务必须准时</li></ul><p>一台最便宜的云主机 + <code>systemd timer</code> 或 <code>cron</code>，能覆盖上面全部需求，成本一个月几十块。<strong>别为了省这点钱，把一个应该常驻的服务硬塞进 Actions。</strong></p>`,29)])])}const E=i(l,[["render",e]]);export{c as __pageData,E as default};
